import type { ReactNode } from "react";

type PageHeaderProps = {
  index: string;
  eyebrow: string;
  title: string;
  description: string;
  aside?: ReactNode;
};

export function PageHeader({ index, eyebrow, title, description, aside }: PageHeaderProps) {
  return (
    <header className="page-header reveal-in">
      <div>
        <div className="page-index"><span>{index}</span>{eyebrow}</div>
        <h1>{title}</h1>
        <p>{description}</p>
      </div>
      {aside ? <div className="page-header__aside">{aside}</div> : null}
    </header>
  );
}
